effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      #define S(a,b,t) smoothstep(a,b,t)

      mat2 Rot(float a)
      {
          float s = sin(a);
          float c = cos(a);
          return mat2(c, -s, s, c);
      }


      // Created by inigo quilez - iq/2014
      // License Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported License.
      vec2 hash( vec2 p )
      {
          p = vec2( dot(p,vec2(2127.1,81.17)), dot(p,vec2(1269.5,283.37)) );
      	return fract(sin(p)*43758.5453);
      }

      float noise( in vec2 p )
      {
          vec2 i = floor( p );
          vec2 f = fract( p );

      	vec2 u = f*f*(3.0-2.0*f);

          float n = mix( mix( dot( -1.0+2.0*hash( i + vec2(0.0,0.0) ), f - vec2(0.0,0.0) ), 
                              dot( -1.0+2.0*hash( i + vec2(1.0,0.0) ), f - vec2(1.0,0.0) ), u.x),
                         mix( dot( -1.0+2.0*hash( i + vec2(0.0,1.0) ), f - vec2(0.0,1.0) ), 
                              dot( -1.0+2.0*hash( i + vec2(1.0,1.0) ), f - vec2(1.0,1.0) ), u.x), u.y);
      	return 0.5 + 0.5*n;
      }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec3 iMouse = vec3(0.5, 0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     umefx = acScreenNorm; 
     // umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     // umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

          vec2 uv = umefx;
          float ratio = iResolution.x / iResolution.y;

          vec2 tuv = uv;
          tuv -= .5;

          // rotate with Noise
          float degree = noise(vec2(iTime*.1, tuv.x*tuv.y));

          tuv.y *= 1./ratio;
          tuv *= Rot(radians((degree-.5)*720.+180.));
      	tuv.y *= ratio;


          // Wave warp with sin
          float frequency = FREQ;
          float amplitude = AMP;
          // float frequency = 5.;
          // float amplitude = 30.;

          float speed = iTime;
          tuv.x += sin(tuv.y*frequency+speed)/amplitude;
         	tuv.y += sin(tuv.x*frequency*1.5+speed)/(amplitude*.5);


          // draw the image
          vec3 colorYellow = color1.rgb;
          // vec3 colorYellow = vec3(.957, .804, .623);
          vec3 colorDeepBlue = color2.rgb;
          // vec3 colorDeepBlue = vec3(.192, .384, .933);
          vec3 layer1 = mix(colorYellow, colorDeepBlue, S(-.3, .2, (tuv*Rot(radians(-5.))).x));

          vec3 colorRed = color3.rgb;
          // vec3 colorRed = vec3(.910, .510, .8);
          vec3 colorBlue = color4.rgb;
          // vec3 colorBlue = vec3(0.350, .71, .953);
          vec3 layer2 = mix(colorRed, colorBlue, S(-.3, .2, (tuv*Rot(radians(-5.))).x));

          vec3 finalComp = mix(layer1, layer2, S(.5, -.3, tuv.y));

          vec3 col = finalComp;

          fragColor = vec4(col,1.0);

 	    vec4 factor = mix(texColorX,fragColor,1.0);
 	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         // float luminance = dot(fragColor.rgb, luminanceWeighting);
         // vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    // if(GRADMAP) { factor = mix(texColorX,gradmap,1.0); }

 	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
